//@description Deform In.position.xyz, the same vertex shader code which is re-used twice in GET_POSITION_VS and GET_PREV_POSITION_VS only with different values
//@inParam In vertex shader input struct (vertex attributes like position,normal,color, etc)
//@inParam instance mesh parameters struct (instance.modelMatrix,visibility etc)
//@inParam object shader parameters struct (textures are here)
//@inParam mTime cTime_s or cPrevTime_s
float3 getCustomPositionVS(VS_INPUT In, PerInstanceParameters& instance, ObjectParameters& object, float mTime)
{
    // =================================
    // cShared0 - wind strength
    // cShared1 - wind vector x component
    // cShared2 - wind vector z component
    float3 deformedPos = In.position.xyz;
#if defined(VERTEX_OFFSET)
    float2 maskMapTexCoords = saturate(convertDefaultTexCoords(In, object, In.texCoords1.xy)); // bring textcoord to 0..1
    // perform wind vertex animation
#if defined(WIND) && !defined(DEPTH_VIS) // avoid shadow artefacts by not animating in the shadow map
    float3 mObjPos = float3(instance.modelMatrix[0][3] + invViewMatrix[0][3],
                            instance.modelMatrix[1][3] + invViewMatrix[1][3],
                            instance.modelMatrix[2][3] + invViewMatrix[2][3]);
    float mObjPosVarSeed = mObjPos.x + mObjPos.y + mObjPos.z;
    // --------------------
    float3 mFreq       = 5.0*In.position.xyz;
    float mAttenuation = In.color.x;
    float3 mOffset     = sin(mTime*8.15 + mFreq.x+mFreq.y+mFreq.z + mObjPosVarSeed)*cos(mTime*3.35 + 0.5*mFreq.x+mFreq.y+mFreq.z + mObjPosVarSeed);
    float3 mOffset1    = 0.002*mOffset;
    float3 mOffset2    =  0.01*mOffset;
    deformedPos += lerp( mOffset1, mOffset2, saturate(cShared0) )*getWindDirection()*mAttenuation;
#endif
    // offset vertically by object.yOffset
    deformedPos = lerp(deformedPos.xyz, deformedPos.xyz+float3(0,object.yOffset,0),maskMapTexCoords.x);
#endif
// perform shaking vertex animation
#if defined(HARVEST_SHAKE)
    float3 shakeOffset = float3(0.0,0.0,0.0); // do not shake vertically
    shakeOffset.x = object.shakeScale.x * saturate(min(object.harvestPosition.w / object.shakeScale.z, 1.0));
    deformedPos += In.gMask * sin(50*mTime) * shakeOffset;
#endif
    return deformedPos;
}
#if defined(FLOATING_ANIMATION)
    //@description Deform In.position.xyz, the same vertex shader code which is re-used twice in GET_POSITION_VS and GET_PREV_POSITION_VS only with different values
    //@inParam In vertex shader input struct (vertex attributes like position,normal,color, etc)
    //@inParam instance mesh parameters struct (instance.modelMatrix,visibility etc)
    //@inParam object shader parameters struct (textures are here)
    //@inParam windStrength wind strength
    //@inParam mTime cTime_s or cPrevTime_s
    //@inParam intensity animation intensity
    float3 getFloatingAnimation(VS_INPUT In, PerInstanceParameters& instance, ObjectParameters& object, float windStrength, float mTime, float intensity)
    {
        float mTimeOffset = 0.0;
        #if defined(VERTEX_COLOR_ANIMATION)
            /*
            mVertexColor.r - controls intensity of animation
            mVertexColor.g - offsets mTime
            mVertexColor.b - unused
            mVertexColor.a - unused
            */
            float4 mVertexColor = In.color.rgba;
            intensity.r *= mVertexColor.r;
            mTimeOffset += mVertexColor.g;
        #endif
        float3 mPos    = In.position.xyz;
        float3 windSideDirection = cross(float3(0,1,0), getWindDirection());
        float3 mObjPos = float3(instance.modelMatrix[0][3] + invViewMatrix[0][3],
                                instance.modelMatrix[1][3] + invViewMatrix[1][3],
                                instance.modelMatrix[2][3] + invViewMatrix[2][3]);
        // Offset time for better animation
        mTime += mTimeOffset;
        // Precompute common terms to reduce redundant calculations
        float3 mCombinedTime = mTime + (windSideDirection + mObjPos.x) + (windSideDirection + mObjPos.z);
        float3 mTrigFactor = cos(mTime + 0.35) * sin(mCombinedTime * 2.0);

        // Perform a Y animation offset using trigonometric functions
        float3 mAnimation = intensity * (mTrigFactor * (windStrength * 0.5));

        // Apply the animation offset to the vertex position
        mPos += mAnimation;

        #if GPU_PROFILE >= GPU_PROFILE_HIGH
            // Calculate small roll to simulate rocking, scaled by wind strength and direction
            float mRollAngle = intensity * windStrength * sin(mTime * 1.5) * 0.13; // Roll around Z-axis
            // Apply roll rotation
            mPos = rotateVectorAroundZ( mPos, mRollAngle );
        #endif
        return mPos;
    }
#endif
#if defined(VERTEX_ANIMATION_TEXTURE)
    //@description Calculate animation texture UV (u = keyframe index, v = object index)
    //@inParam In vertex shader input struct (vertex attributes like position,normal,color, etc)
    //@inParam animTexSize XY size of the texture (amount of pixels horizontally/vertically)
    //@inParam animTime 0..1 scrolling time based parameter
    float2 getAnimationKeyframeUV( VS_INPUT In, float2 animTexSize, float animTime) {
        // Calculate animation texture UV (u = keyframe index, v = object index)
        float2 uv;
        uv.x = ((animTexSize.x-1)*saturate(animTime)+0.5) / animTexSize.x;
        uv.y = (getMergeChildrenObjectDataIndexAsFloat(In) + 0.5) / animTexSize.y;
        return uv;
    }
    //@description load position(XYZ transaltion, localSpace) of the pieces from the animationArray[0] texture\n
    //texture sampled using samplerBilinearClamp filter, so interpolation for values in-between(pixels) comes for free
    //@inParam object shader parameters struct (textures are here)
    //@inParam uv animated texture UVs (u = keyframe index, v = object index)
    float4 getPositionTex(ObjectParameters& object, float2 uv) {
        return tex2DSampleLod( animationArray, samplerBilinearClamp, uv.xy, uint(0),0);
    }
    //@description load orient(XYZW quaternion rotation, localSpace) of the pieces from the animationArray[1] texture\n
    //texture sampled using samplerBilinearClamp filter, so interpolation for values in-between(pixels) comes for free\n
    //Note: quaternion rotations must be compatible (this should be done on content side)
    //@inParam object shader parameters struct (textures are here)
    //@inParam uv animated texture UVs (u = keyframe index, v = object index)
    float4 getOrientTex(ObjectParameters& object, float2 uv) {
        return tex2DSampleLod( animationArray, samplerBilinearClamp, uv.xy, uint(1),0);
    }
    //@description Deform In.position.xyz, the same vertex shader code which is re-used twice in GET_POSITION_VS and GET_PREV_POSITION_VS only with different values
    //@inParam In vertex shader input struct (vertex attributes like position,normal,color, etc)
    //@inParam object shader parameters struct (textures are here)
    //@inParam mPosition XYZ transaltion, W not used
    //@inParam mOrient XYZW quaternion rotation
    float3 getVtxAnimTexturePositionVS( VS_INPUT In, ObjectParameters& object, float4 mPosition, float4 mOrient ){
        float4 localPosition = mPosition;
        float4 localOrient   = mOrient;
        float3 mInitialPosition = In.position.xyz;
        #if defined(VERTEX_OFFSET)
            float2 maskMapTexCoords = saturate(convertDefaultTexCoords(In, object, In.texCoords1.xy)); // bring textcoord to 0..1
            // offset vertically by object.yOffset
            mInitialPosition = lerp(mInitialPosition.xyz, mInitialPosition.xyz+float3(0,object.yOffset,0),maskMapTexCoords.x);
        #endif
        // apply quaternion rotation
        float3 mDeformed = quaternionRotate( localOrient, mInitialPosition );
        // apply translation
        mDeformed += localPosition.xyz;
        return mDeformed;
    }
    //@description Deform mVector (In.normal.xyz,In.tangent.xyz), used in GET_NORMAL_VS, GET_TANGENT_VS
    //@inParam In vertex shader input struct (vertex attributes like position,normal,color, etc)
    //@inParam object shader parameters struct (textures are here)
    //@inParam mVector vector to transform, usually In.normal.xyz, In.tangent.xyz
    //@inParam mOrient XYZW quaternion rotation
    float3 getVtxAnimTextureVectorVS( VS_INPUT In, ObjectParameters& object, float3 mVector, float4 mOrient ){
        float4 localOrient = mOrient;
        // apply quaternion rotation
        float3 mDeformed = quaternionRotate( localOrient, mVector );
        return mDeformed;
    }
#endif

#if defined(HARVEST_SHAKE)
    float gMask;
#endif
#if defined(VERTEX_ANIMATION_TEXTURE)
    uint2 gAnimTexSize;
    float2 gAnimUV;
    float2 gPrevAnimUV;
    float4 gPosition;
    float4 gPrevPosition;
    float4 gOrient;
    float4 gPrevOrient;
#endif

#if defined(HARVEST_SHAKE)
    float3 fullWorldPosition = mul(instance.modelMatrix, float4(In.position.xyz, 1))+ float3(invViewMatrix[0][3], invViewMatrix[1][3], invViewMatrix[2][3]);
    // sphere mask based on harvestPosition.xyz (worldSpace) and fullWorldPosition.xyz of the vertices
    In.gMask = saturate(1.0-min(distance(object.harvestPosition.xyz,fullWorldPosition.xyz)/object.shakeScale.w,1.0));
#endif
#if defined(VERTEX_ANIMATION_TEXTURE)
    In.gAnimTexSize  = tex2DSize(animationArray,0).xy;
    In.gAnimUV       = getAnimationKeyframeUV(In, (float2)In.gAnimTexSize, object.scrollPos).xy;
    In.gPrevAnimUV   = getAnimationKeyframeUV(In, (float2)In.gAnimTexSize, object.prevScrollPos).xy;
    In.gPosition     = getPositionTex(object, In.gAnimUV);
    In.gPrevPosition = getPositionTex(object, In.gPrevAnimUV);
    In.gOrient       = getOrientTex(object, In.gAnimUV);
    In.gPrevOrient   = getOrientTex(object, In.gPrevAnimUV);
#endif

{
    float3 mDeformed = In.position.xyz;
    #if defined(FLOATING_ANIMATION)
        mDeformed = getFloatingAnimation(In, instance, object, cShared0, cTime_s, object.animationIntensity.r);
    #elif defined(VERTEX_ANIMATION_TEXTURE)
        mDeformed = getVtxAnimTexturePositionVS(In, object, In.gPosition, In.gOrient);
    #else
        // DEFAULT BEHAVIOUR
        mDeformed = getCustomPositionVS(In, instance, object, cTime_s);
    #endif
    #if defined(SKINNING)
        return skinPoint(mDeformed.xyz, In, instance, object);
    #else
        return mDeformed.xyz;
    #endif
}

{
    float3 mDeformed = In.position.xyz;
    #if defined(FLOATING_ANIMATION)
        mDeformed = getFloatingAnimation(In, instance, object, cShared0, cPrevTime_s, object.animationIntensity.r);
    #elif defined(VERTEX_ANIMATION_TEXTURE)
        mDeformed = getVtxAnimTexturePositionVS(In, object, In.gPrevPosition, In.gPrevOrient);
    #else
        // DEFAULT BEHAVIOUR
        mDeformed = getCustomPositionVS(In, instance, object, cPrevTime_s);
    #endif
    #if defined(SKINNING)
        return skinPrevPoint(mDeformed.xyz, In, instance, object);
    #else
        return mDeformed.xyz;
    #endif
}

#if !defined(SKINNING)
    prevWorldPosition = mul(instance.prevModelMatrix, float4(prevPosition, 1));
#endif

#if defined(VERTEX_ANIMATION_TEXTURE)
    return getVtxAnimTextureVectorVS(In, object, In.normal.xyz, In.gOrient);
#endif

#if defined(VERTEX_ANIMATION_TEXTURE)
    return getVtxAnimTextureVectorVS(In, object, In.tangent.xyz, In.gOrient);
#endif

    float3 localPosition : TEXCOORDn;
    float3 localNormal   : TEXCOORDn;
#if defined(VERTEX_ANIMATION_TEXTURE)
    float  hideIndex    : TEXCOORDn;
#endif
#if defined(NORMAL_UV1)
    float2 normalMaskTexCoords : TEXCOORDn;
#endif

    Out.localPosition = In.position.xyz;
    Out.localNormal = normalize(In.normal.xyz);
#if defined(NORMAL_UV1)
    Out.normalMaskTexCoords = convertDefaultTexCoords(In, object, In.texCoords1.xy); // Pass second UVSet to the Pixel Shader
#endif

#if defined(MERGE_CHILDREN_HIDE_BY_INDEX)
    if (object.hideByIndex.x > getMergeChildrenObjectDataIndexAsFloat(In)){
        //Out.position = float4(0,0,0,-1); // remove from pixel shader
        Out.position = float4(-1000000.0f, -1000000.0f, -1000000.0f, 1.0f);
    }
#endif
#if defined(VERTEX_ANIMATION_TEXTURE)
    float mIndex = getMergeChildrenObjectDataIndexAsFloat(In);
    Out.hideIndex = saturate( -1 + 2*object.hidePieces.x + mIndex/(float(In.gAnimTexSize.y) - 1)) * 4;
#endif

#if defined(CUSTOM_PARALLAX)
    return fixDDSCompressionHeightMap(tex2DSampleGrad(mParallaxMap, standardMaterialSampler, uv, layer, gradX, gradY).x);
#endif

#if defined(CUSTOM_PARALLAX)
    return fixDDSCompressionHeightMap(tex2DSample(mParallaxMap, standardMaterialSampler, uv, layer).x);
#endif

#if defined(CUSTOM_PARALLAX)
    return tex2DSize(mParallaxMap, 0);
#endif

// Custom pixel functions
#include "$data/shaders/sharedFunctions_fs.gsl"
// Extra functions related to the placeableShader only

#if defined(ROCK_DETAIL)
    //@description Calculates top projected mask (worldSpace) based on worldSpace normal of the pixel shader
    //@inParam mNormal worldSpace normal (already with normalMap)
    //@inParam mMossLevel [0..1] control the intensity of the dirt/moss mask
    float getMossMask(float3 mNormal, float mMossLevel){
        float mTransition = 1 - (mMossLevel * mMossLevel);
        float NdotY = mNormal.y ; // dot(mNormal, float3(0.0, 1.0, 0.0));
        float mMossMask = saturate(NdotY - mTransition);
        return mMossMask * mMossMask * mMossMask;
    }
#endif
#if defined(VERTEX_ANIMATION_TEXTURE)
    //@description Perform clip Screen-based alpha-test semi-transparent alpha\n
    //Uses In.vs.hideIndex to control opacity, hideIndex pre-calculated from MergeChildren Index
    //@inParam In pixel shader input struct (screenPos,worldNormal,vertexColor,etc)
    void doAlphaMaskCustom(FS_INPUT In){
        int2 pixelPos = int2(floor(viewportSize.xy * In.vs.screenPos.xy/In.vs.screenPosW)) & 1;
        int N = (pixelPos.x + 2 * pixelPos.y + 1) & 3;  // 1 2
                                                        // 3 0
        if (round(In.vs.hideIndex) > (float)N) {
            clip(-1);
        }
    }
#endif

    float  gSnowMask;  // top-down projected snow-mask animated by cShared4
    bool   gIsSnowing; // if its snowing or not
    float3 gSnowDiffuse; 
    float3 gSnowSpecular;
    float  gSnowMaskGradient; // black-and-white mask where snow is
    bool   gIsWetActivated;   // if its wet or not
    float  gWetnessMask;
    float2 gWaterDroplets;// water droplets normalMap
#if defined(ROCK_DETAIL)
    float3 gNormalMapDetail;
    float3 gMossMapDetail;
    float  gMossLevel;
#endif
#if defined(TERRAIN_VT)
    float3 gTerrainNormal;
    float3 gTerrainDiffuse;
    float  gTerrainRoughness;
    float  gTerrainHeightMask;
#endif

{
    float3 mAbsNormal   = abs(In.vs.localNormal);
    mAbsNormal /= (mAbsNormal.x + mAbsNormal.y + mAbsNormal.z);
    float2 texCoordsX = In.vs.localPosition.zy;
    float2 texCoordsY = In.vs.localPosition.zx;
    float2 texCoordsZ = In.vs.localPosition.xy;
    float2 uvs = mAbsNormal.x > mAbsNormal.y ? (mAbsNormal.x > mAbsNormal.z ? texCoordsX : texCoordsZ) : (mAbsNormal.y > mAbsNormal.z ? texCoordsY : texCoordsZ);
    globals.gSnowDiffuse  = float3(0.7300,0.7668,0.8356);
    // snow texture is 1024x1024 so we need to scale uv's
    globals.gSnowSpecular = tex2DSample( mSnowSpecular, standardMaterialSampler, 0.5*uvs ).rgb;
    // the same scale like in vehicleShader
    globals.gWaterDroplets.xy = tex2DSample( waterDroplets, standardMaterialSampler, 1.5*uvs ).xy;
    #if defined(ROCK_DETAIL)
        globals.gNormalMapDetail = tex2DSample(mNormalDetail,standardMaterialSampler,0.5*uvs ).rgb;
        globals.gMossMapDetail   = tex2DSample(mMossDetail,standardMaterialSampler,2.0 * uvs).rgb;
        globals.gMossLevel = object.mossLevel;
    #endif
    globals.gSnowMask  = 0.0;
    globals.gSnowMaskGradient = 1.0;
    bool snowWetnessUV = In.vs.defaultTexCoords.x > 0.0;
    globals.gIsSnowing = cShared4 > 0.001 && object.snowScale > 0.0 && snowWetnessUV;
    globals.gIsWetActivated = cWetness > 0.001 && object.wetnessScale > 0.0 && snowWetnessUV;
    globals.gWetnessMask = cWetness * object.wetnessScale * getRainOcclusionFactor(getWorldPosition(In));
    #if defined( GLOSS_MAP )
        globals.gSnowMaskGradient = tex2DSample(glossMap, GLOSS_MAP_SAMPLER, GLOSS_MAP_TEXCOORDS).a;
    #endif
    #if defined(CUSTOM_SNOWMASK)
        globals.gSnowMaskGradient *= tex2DSample(mCustomSnowMask, standardMaterialSampler, GLOSS_MAP_TEXCOORDS).r;
    #endif
}
#if defined(TERRAIN_VT)
    float3 worldPos = getWorldPosition(In);
    worldPos.y = worldPos.y + object.heightMask;
    float displacement = object.bool_displacement;
    globals.gTerrainNormal  = getTerrainWorldspaceNormal(In, worldPos);
    globals.gTerrainDiffuse = getTerrainDiffuse(In, worldPos);
    globals.gTerrainRoughness = getTerrainRoughness(In, worldPos);
    globals.gTerrainHeightMask = getHeightAboveTerrain(worldPos, displacement);
#endif
#if defined(HIDE_UV_SHIFT) || defined(HIDE_ALPHA)
    float sectionIndex;
    float4 hideSectionStates = object.hideSectionStates;

    #if defined(UV_BASED_SECTIONS)
        sectionIndex = floor(In.vs.defaultTexCoords.x);
        float hideSectionState = float(sectionIndex  == 0) + hideSectionStates.x * float(sectionIndex  == 1) + hideSectionStates.y * float(sectionIndex  == 2) + hideSectionStates.z * float(sectionIndex  == 3);
    #else
        sectionIndex = floor(In.vs.defaultTexCoords.x * 3);
        float hideSectionState = hideSectionStates.x * float(sectionIndex  == 0) + hideSectionStates.y * float(sectionIndex  == 1) + hideSectionStates.z * float(sectionIndex  == 2);
    #endif

    // check if uvs are in hide area
    float2 uvs = In.vs.defaultTexCoords;
    float4 hideArea = object.hideArea;
    #if defined(UV_BASED_SECTIONS)
        uvs.x -= sectionIndex;
    #endif

    float hideIsInArea = float((uvs.x > hideArea.x) && (uvs.x < hideArea.y) && (uvs.y > hideArea.z) && (uvs.y < hideArea.w));

    #if defined(HIDE_UV_SHIFT)
        // if hideSection is active we want to shift the uvs. otherwise take the original uvs
        In.vs.defaultTexCoords.y += object.hideShiftOffset * hideSectionState * hideIsInArea;
    #endif
#endif

#if defined( NORMAL_MAP )
    #if defined(NORMAL_UV1)
        float3 mNormal = tex2DSample(normalMap,standardMaterialSampler,In.vs.normalMaskTexCoords).xyz - 0.5;
    #else // DEFAULT BEHAVIOUR
        float3 mNormal = tex2DSample(normalMap,standardMaterialSampler,NORMAL_MAP_TEXCOORDS).xyz - 0.5;
    #endif
    #if defined( ROCK_DETAIL )
        mNormal.xy += globals.gNormalMapDetail.xy-0.5;
    #endif
    if (globals.gIsWetActivated) {
        mNormal = makeWetNormal(mNormal,globals.gWaterDroplets.xy,globals.gWetnessMask);
    }
    return mNormal;
#endif

#if defined( NORMAL_MAP )
    return normalize(getUnnormalizedTangentSpaceNormal(In, globals, instance, object));
#endif

#if defined(CUSTOM_BLEND)
    float3 customDiffuse = tex2DSample(mCustomDiffuse, standardMaterialSampler, ALBEDO_MAP_TEXCOORDS).rgb;
    #if defined(CUSTOM_MASK_BLEND)
        float alphaMask = tex2DSample(mAlphaMask, standardMaterialSampler, ALBEDO_MAP_TEXCOORDS).r;
        diffuseColor.rgb = lerp(diffuseColor.rgb, customDiffuse.rgb, alphaMask * object.blendScale).rgb;
    #else
        diffuseColor.rgb = lerp(diffuseColor.rgb, customDiffuse.rgb, object.blendScale);
    #endif
#endif
#if defined(ROCK_DETAIL)
    float gMossMask = getMossMask(normal, globals.gMossLevel);
    diffuseColor.rgb = lerp(diffuseColor.rgb, globals.gMossMapDetail, gMossMask);
    diffuseColor.rgb *= globals.gSnowSpecular.g; // added extra details from snow specular.g
#endif
#if defined(TERRAIN_VT)
    // using a liniar interp function to mix original diffuse color using the function getHeightAboveTerrain as mask
    diffuseColor = lerp(diffuseColor, globals.gTerrainDiffuse, 1 - saturate(globals.gTerrainHeightMask));
    // mixing worldSpace normal
    normal = lerp( normal, globals.gTerrainNormal, 1 - saturate(globals.gTerrainHeightMask));
#endif
    { // Snow mixing code
        if (globals.gIsSnowing){
            // pixelShader normal computed before this point, right after PARALLAX_MAPPING_FS
            // globals.gSnowSpecular.g - ambient occlusion used as alpha (should be less than 1.0)
            globals.gSnowMask = getSnowMaskFromWorldNormalNoiseMask(object.snowScale,normal,0.25,globals.gSnowSpecular.g,globals.gSnowMaskGradient).y;
            diffuseColor.rgb = lerp( diffuseColor.rgb, globals.gSnowDiffuse.rgb, globals.gSnowMask );
        }
    }
    // placeable Color
    if (object.placeableColorScale.w > 0){
        diffuseColor = lerp(diffuseColor,object.placeableColorScale.rgb,saturate(0.1+getFresnel( facing, 0.15 , 4.0 ))*object.placeableColorScale.w);
    }

#if defined(ROCK_DETAIL)
    // mixing roughness with smoothness
    roughness = saturate(roughness*globals.gNormalMapDetail.b);
#endif
#if defined(TERRAIN_VT)
    //mixing roughness with terrain roughness
    roughness = lerp(roughness, globals.gTerrainRoughness, 1 - saturate(globals.gTerrainHeightMask));
#endif
    { // Snow mixing code
        if (globals.gIsSnowing){
            float3 mPbrMapValues = lerp( float3(1-roughness,bakedAO,metalness), globals.gSnowSpecular, globals.gSnowMask );
            roughness = 1-mPbrMapValues.x;
            bakedAO   = mPbrMapValues.y;
            metalness = mPbrMapValues.z;
        }
    }

porosityAtZeroRoughness = object.porosityBySmoothness.x;
porosityRoughnessSlope  = object.porosityBySmoothness.y;
// porosity = porosityAtZeroRoughness + roughness * porosityRoughnessSlope;
if(globals.gIsWetActivated) {
    //porosity = 0.25;
    wetness = globals.gWetnessMask;
}

#if defined(ALPHA_MAP)
    // load alpha from separate texture
    alpha = tex2DSample(alphaMap, standardMaterialSampler, ALBEDO_MAP_TEXCOORDS).x;
#endif
#if defined(ALPHA_BLENDED) && defined(DECAL_RENDER)
    reflectingLightingScale = alpha;
#endif
    { // Snow mixing code
        #if defined(ALPHA_BLENDED)
            if (globals.gIsSnowing){
                alpha = lerp(alpha,1.0,globals.gSnowMask);
            }
        #endif
        #if defined(HIDE_ALPHA)
            alpha *= 1 - (hideIsInArea * (1 - hideSectionState));
        #endif
    }

#if defined(VERTEX_ANIMATION_TEXTURE)
{
    if ( object.hidePieces.x > 0 ){
        doAlphaMaskCustom(In);
    }
}
#endif

#if defined(DEBUG_SHOW_CUSTOM1)
    oColor.xyz *= 0.0001;
    #if defined(ROCK_DETAIL)
        oColor.xyz = lerp(oColor.xyz, float3(1.0,1.0,1.0), gMossMask);
    #endif
#endif
#if defined(DEBUG_SHOW_CUSTOM2)
    oColor.xyz *= 0.0001;
    #if defined(TERRAIN_VT)
        oColor.xyz = lerp(oColor.xyz, float3(1.0,1.0,1.0), 1 - saturate(globals.gTerrainHeightMask));
    #endif
#endif
